import {CAMERA_FIELDS,CONTROL_FIELDS,CAMERA_DEFAULTS,CONTROL_DEFAULTS,DEFAULT_BINDINGS,BINDING_LABELS,normalizeCamera,normalizeControls,normalizeBindings,bindingCodes,bindingName,bindingConflict,validBinding} from './preferences.js';
const node=id=>document.getElementById(id);
export function setupSettings(settings,{save,apply}){
 const ranges=[],buttons=new Map();let capture=null;
 const status=message=>{node('settings-status').textContent=message;};
 function buildRanges(container,fields,group){for(const field of fields){const label=document.createElement('label'),title=document.createElement('span'),output=document.createElement('output'),input=document.createElement('input');label.className='range-setting';title.textContent=field.label;input.type='range';input.id=group+'-'+field.key;input.min=field.min;input.max=field.max;input.step=field.step;output.setAttribute('for',input.id);label.htmlFor=input.id;label.append(title,output,input);container.append(label);ranges.push({input,output,field,group});input.addEventListener('input',()=>{settings[group][field.key]=Number(input.value);apply(group);refreshRanges();});input.addEventListener('change',()=>{save();status('Settings saved.');});}}
 buildRanges(node('camera-ranges'),CAMERA_FIELDS,'camera');buildRanges(node('control-ranges'),CONTROL_FIELDS,'controls');
 function refreshRanges(){for(const {input,output,field,group}of ranges){input.value=settings[group][field.key];output.value=(field.step<1?Number(input.value).toFixed(2):input.value)+(field.unit?' '+field.unit:'');input.setAttribute('aria-valuetext',output.value);}}
 function refreshBindings(){
  for(const [action,button]of buttons){button.textContent=bindingName(settings.bindings[action]);button.setAttribute('aria-label',BINDING_LABELS[action]+': '+bindingName(settings.bindings[action])+'. Change binding.');}
  const list=node('controls-bindings');list.replaceChildren();for(const [action,label]of Object.entries(BINDING_LABELS)){const row=document.createElement('div'),key=document.createElement('kbd'),description=document.createElement('span');key.textContent=bindingCodes(settings.bindings,action).map(bindingName).join(' / ');description.textContent=label;row.append(key,description);list.append(row);}
  const hint=document.querySelector('.controls-hint');if(hint)hint.textContent=`${bindingName(settings.bindings.jump)} JUMP  ·  ${bindingName(settings.bindings.boost)} BOOST  ·  ${bindingName(settings.bindings.drift)} SLIDE`;
 }
 function cancelCapture(){capture=null;node('binding-capture').hidden=true;}
 function commitBinding(code){
  if(!capture)return;if(!validBinding(code)){node('binding-capture-message').textContent='That key is reserved. Choose a different key, or Escape to cancel.';return;}const conflict=bindingConflict(settings.bindings,capture,code);if(conflict){node('binding-capture-message').textContent=`Already used for ${BINDING_LABELS[conflict].toLowerCase()}. Choose another input.`;return;}
  const action=capture;settings.bindings={...settings.bindings,[action]:code};cancelCapture();apply('controls');save();refreshBindings();buttons.get(action).focus();status(BINDING_LABELS[action]+' set to '+bindingName(code)+'.');
 }
 for(const [action,label]of Object.entries(BINDING_LABELS)){const row=document.createElement('div'),text=document.createElement('span'),button=document.createElement('button');row.className='keybind-row';text.textContent=label;button.type='button';button.className='bind-button';buttons.set(action,button);row.append(text,button);node('keybind-list').append(row);button.addEventListener('click',()=>{capture=action;node('binding-capture').hidden=false;node('binding-capture-label').textContent=label;node('binding-capture-message').textContent='Press a key or mouse button. Escape cancels.';node('cancel-binding').focus();node('binding-capture-label').scrollIntoView?.({block:'center'});});}
 window.addEventListener('keydown',e=>{if(!capture)return;e.preventDefault();e.stopImmediatePropagation();if(e.code==='Escape'||(e.code==='Enter'&&e.target===node('cancel-binding')))cancelCapture();else if(!e.repeat)commitBinding(e.code);},true);
 window.addEventListener('pointerdown',e=>{if(!capture||e.target===node('cancel-binding'))return;e.preventDefault();e.stopImmediatePropagation();commitBinding('Mouse'+e.button);},true);
 node('binding-capture').addEventListener('contextmenu',e=>e.preventDefault());node('cancel-binding').addEventListener('click',cancelCapture);node('settings-dialog').addEventListener('close',cancelCapture);
 const tabs=[...document.querySelectorAll('[data-settings-tab]')];function selectTab(tab,focus=false){cancelCapture();for(const button of tabs){const selected=button===tab;button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1;node('panel-'+button.dataset.settingsTab).hidden=!selected;}if(focus)tab.focus();}
 for(const tab of tabs){tab.addEventListener('click',()=>selectTab(tab));tab.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.code))return;e.preventDefault();const index=tabs.indexOf(tab),next=e.code==='Home'?0:e.code==='End'?tabs.length-1:(index+(e.code==='ArrowRight'?1:-1)+tabs.length)%tabs.length;selectTab(tabs[next],true);});}
 node('reset-camera').addEventListener('click',()=>{settings.camera=normalizeCamera(CAMERA_DEFAULTS);apply('camera');save();refreshRanges();status('Camera defaults restored.');});
 node('reset-controls').addEventListener('click',()=>{settings.controls=normalizeControls(CONTROL_DEFAULTS);settings.bindings=normalizeBindings(DEFAULT_BINDINGS);node('invert-pitch').checked=false;apply('controls');save();refreshRanges();refreshBindings();status('Controls restored.');});
 node('invert-pitch').addEventListener('change',()=>{settings.controls.invertPitch=node('invert-pitch').checked;apply('controls');save();status('Controls saved.');});
 const volume=node('master-volume');volume.addEventListener('input',()=>{settings.volume=Number(volume.value);node('volume-value').value=volume.value+'%';apply('audio');});volume.addEventListener('change',()=>{save();status('Volume saved.');});
 function sync(){refreshRanges();refreshBindings();node('invert-pitch').checked=settings.controls.invertPitch;volume.value=settings.volume;node('volume-value').value=settings.volume+'%';}sync();return {sync,cancelCapture};
}
